Output component code in XML format as follows:
<ComponentArtifact name="ComponentName">
  <ComponentFile fileName="App.vue" isEntryFile="true">
    <template>
      <ComponentName v-bind="mockProps" />
    </template>

    <script setup lang="ts">
    import { ComponentName } from './ComponentName.vue';
    import { ref } from 'vue';

    const mockProps = ref({
      // Define mock data here
    });
    </script>
  </ComponentFile>

  <ComponentFile fileName="ComponentName.vue">
    <template>
      <!-- Main component implementation -->
    </template>

    <script setup lang="ts">
    import { ref, defineProps } from 'vue';
    import { Props } from './types';

    const props = defineProps<Props>();
    // Component implementation
    </script>

    <style lang="less" scoped>
    /* Component styles */
    </style>
  </ComponentFile>

  <ComponentFile fileName="types.ts">
    // Type definitions for component props
    export interface Props {
      // Define props interface
    }
  </ComponentFile>
</ComponentArtifact>
